// Supabase Keys
const SUPABASE_URL = 'https://zwmgzepftzayzgvgwndp.supabase.co/rest/v1/';
const SUPABASE_KEY = 'sb_publishable_RFdnWIB4bMs1zz4qkXcdZQ__JL7YmIf';

let supabaseClient = null;

if (typeof supabase !== 'undefined') {
  supabaseClient = supabase.createClient(SUPABASE_URL, SUPABASE_KEY);
}

document.addEventListener('DOMContentLoaded', () => {
  const depositForm = document.getElementById('depositForm');
  if (depositForm) {
    depositForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      
      const email = document.getElementById('userEmail').value;
      const amount = document.getElementById('depositAmount').value;
      const trxId = document.getElementById('trxId').value;
      const msg = document.getElementById('responseMsg');

      msg.innerText = "درخواست بھیجی جا رہی ہے...";
      msg.style.color = "yellow";

      if (!supabaseClient) {
        msg.innerText = "Supabase کنیکٹ نہیں ہو سکا۔";
        msg.style.color = "red";
        return;
      }

      const { data, error } = await supabaseClient
        .from('deposits')
        .insert([
          { user_email: email, amount: parseFloat(amount), trx_id: trxId, status: 'Pending' }
        ]);

      if (error) {
        msg.innerText = "خرابی: " + error.message;
        msg.style.color = "red";
      } else {
        msg.innerText = "درخواست موصول ہو گئی! مینوئل تصدیق کے بعد بیلنس ایڈ ہو جائے گا۔";
        msg.style.color = "#00c853";
        depositForm.reset();
      }
    });
  }
});